'use client';
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode, type FormEvent } from 'react';
import { Zap, LayoutDashboard, ClipboardList, CalendarDays, Cpu, Box, Sparkles, Users, History, Settings2, CircleHelp, Search, Bell, ChevronDown, ArrowUpRight, ArrowRight, Plus, Clock3, CircleCheck, TriangleAlert, ChevronLeft, ChevronRight, SlidersHorizontal, Download, ArrowUp, ArrowDown, Wrench, Check, X, LogOut, ShieldCheck, MapPin, Paperclip, Send, RefreshCw, CircleDot, Activity as ActivityIcon, Loader2, Info, FileText, CheckCheck, UserRound, CalendarClock, LockKeyhole } from 'lucide-react';
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarMenu, SidebarMenuItem, SidebarMenuButton, SidebarProvider, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@/components/ui/sheet';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '@/components/ui/table';
import { Progress } from '@/components/ui/progress';
import { Empty, EmptyHeader, EmptyTitle, EmptyDescription, EmptyMedia } from '@/components/ui/empty';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import DigitalTwin from '@/components/digital-twin';
import { forecast } from '@/lib/forecast';
import { dateLabel, dayISO, done, manager, priorityLabels, roleLabels, statusLabels, todayISO, type Equipment, type Person, type PortalState, type Priority, type Role, type Status, type Ticket } from '@/lib/portal-types';

const navigation=[{key:'overview',label:'Обзор',icon:LayoutDashboard},{key:'requests',label:'Заявки',icon:ClipboardList},{key:'ppr',label:'График ППР',icon:CalendarDays},{key:'equipment',label:'Оборудование',icon:Cpu},{key:'digital-twin',label:'3D-аналитика',icon:Box},{key:'analytics',label:'ИИ-аналитика',icon:Sparkles}];
const pageNames:Record<string,string>={overview:'Обзор электрослужбы',requests:'Заявки на обслуживание',ppr:'График ППР',equipment:'Оборудование','digital-twin':'3D-аналитика',analytics:'ИИ-аналитика',team:'Команда и права',activity:'Журнал событий',profile:'Личный кабинет',help:'Помощь и регламент'};
const initials=(name:string)=>name.split(' ').slice(0,2).map(n=>n[0]).join('');
const formatHours=(n:number)=>Number(n.toFixed(1)).toLocaleString('ru-RU');
function Avatar({person,small=false}:{person?:Person;small?:boolean}){return <span className={`avatar ${small?'avatar-sm':''} avatar-${(person?.name?.charCodeAt(0)??0)%4}`}>{person?initials(person.name):'—'}</span>}
function StateBadge({status}:{status:Status}){return <span className={`status-badge status-${status}`}><span/>{statusLabels[status]}</span>}
function PriorityMark({priority}:{priority:Priority}){return <span className={`priority priority-${priority}`}><i><b/><b/><b/></i>{priorityLabels[priority]}</span>}
function Choice({value,onChange,options,label,className=''}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];label:string;className?:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={className}><SelectValue/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function NoData({title='Пока ничего нет',text='Новые записи появятся здесь.',icon:Icon=ClipboardList}:{title?:string;text?:string;icon?:typeof ClipboardList}){return <Empty className="empty-block"><EmptyHeader><EmptyMedia variant="icon"><Icon/></EmptyMedia><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{text}</EmptyDescription></EmptyHeader></Empty>}
function Panel({title,children,action,className='',subtitle}:{title:string;children:ReactNode;action?:ReactNode;className?:string;subtitle?:string}){return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function NavItem({item,current,navigate,count}:{item:{key:string;label:string;icon:typeof Zap};current:string;navigate:(k:string)=>void;count?:number}){const {setOpenMobile}=useSidebar();return <SidebarMenuItem><SidebarMenuButton asChild isActive={current===item.key} className="nav-link"><a href={item.key==='overview'?'/':`/${item.key}`} onClick={e=>{e.preventDefault();navigate(item.key);setOpenMobile(false)}}><item.icon/><span>{item.label}</span>{count!==undefined&&count>0&&<b className="nav-count">{count}</b>}{item.key==='analytics'&&<span className="nav-ai">AI</span>}</a></SidebarMenuButton></SidebarMenuItem>}

type Mutate=(action:string,data:unknown)=>Promise<{ok:boolean;id?:string}>;
export default function Portal({initial,section:initialSection}:{initial:PortalState;section:string}){
 const [live,setLive]=useState(initial),[section,setSection]=useState(initialSection),[search,setSearch]=useState(''),[period,setPeriod]=useState('7'),[requestTab,setRequestTab]=useState('active'),[priorityFilter,setPriorityFilter]=useState('all'),[modal,setModal]=useState<string|null>(null),[selected,setSelected]=useState<string|null>(null),[equipmentEdit,setEquipmentEdit]=useState<Equipment|undefined>(),[notifications,setNotifications]=useState(false),[busy,setBusy]=useState(false),[weekOffset,setWeekOffset]=useState(0),[capacity,setCapacity]=useState('6');
 const data=live,me=data.me,admin=me?.role==='admin',manage=manager(me?.role),today=todayISO();
 const active=data.tickets.filter(t=>!done(t)),overdue=active.filter(t=>t.due_date<today),completed=data.tickets.filter(t=>t.status==='closed'&&t.closed_at&&t.closed_at.slice(0,10)>=dayISO(-Number(period))),ppr=data.tickets.filter(t=>t.kind==='ppr');
 const predictions=useMemo(()=>forecast(data.tickets,data.people,Number(capacity)),[data.tickets,data.people,capacity]);
 const selectedTicket=data.tickets.find(t=>t.id===selected);
 const pending=data.people.filter(p=>p.role==='pending');
 const navigate=useCallback((key:string)=>{setSection(key);window.history.pushState({},'',key==='overview'?'/':`/${key}`);window.scrollTo({top:0,behavior:'smooth'})},[]);
 useEffect(()=>{const fn=()=>setSection(window.location.pathname.split('/')[1]||'overview');window.addEventListener('popstate',fn);return()=>window.removeEventListener('popstate',fn)},[]);
 const refresh=useCallback(async()=>{const r=await fetch('/api/portal',{cache:'no-store'});const payload=await r.json() as PortalState;if(!r.ok||payload.error)throw new Error(payload.error||'Не удалось обновить данные');setLive(payload);return payload as PortalState},[]);
 const run:Mutate=useCallback(async(action,payload)=>{
  setBusy(true);
  try{const r=await fetch('/api/portal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data:payload})});const result=await r.json() as {ok:boolean;id?:string;error?:string};if(!r.ok)throw new Error(result.error||'Не удалось сохранить');await refresh();toast.success(action==='register'?'Профиль зарегистрирован':'Изменения сохранены');return result;}catch(e){toast.error(e instanceof Error?e.message:'Не удалось сохранить');return {ok:false}}finally{setBusy(false)}
 },[refresh]);
 const runRef=useRef(run),stateRef=useRef(data);runRef.current=run;stateRef.current=data;
 useEffect(()=>{
  const context=(document as unknown as {modelContext?:{registerTool:(tool:unknown,options:{signal:AbortSignal})=>unknown}}).modelContext;if(!context?.registerTool)return;const controller=new AbortController();
  const tools=[{name:'list_service_requests',title:'Список заявок электрослужбы',description:'Read the requests currently accessible to this signed-in user. Does not change data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return stateRef.current.tickets.map(t=>({id:t.id,number:t.number,title:t.title,status:t.status,due_date:t.due_date}))}},{name:'start_service_request_creation',title:'Открыть форму заявки',description:'Open the new service request form. Does not create or submit a request.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');setModal('request');return {opened:true}}}];
  for(const tool of tools){try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}
  return()=>controller.abort();
 },[]);
 function exportCSV(tickets:Ticket[]){const rows=[['Номер','Название','Объект','Статус','Приоритет','Срок','Исполнитель','План, ч','Факт, ч'],...tickets.map(t=>[t.number,t.title,t.location,statusLabels[t.status],priorityLabels[t.priority],t.due_date,data.people.find(p=>p.id===t.assignee_id)?.name??'',t.estimated_hours,t.actual_hours??''])];const csv='\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`volt-${today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast.success('Отчёт выгружен в CSV')}
 const restricted=['pending','blocked'].includes(me?.role??'');
 const searched=data.tickets.filter(t=>`${t.title} ${t.number} ${t.location}`.toLowerCase().includes(search.toLowerCase()));
 const filtered=searched.filter(t=>(priorityFilter==='all'||t.priority===priorityFilter)&&(requestTab==='all'||requestTab==='active'&&!done(t)||requestTab==='mine'&&(t.assignee_id===me?.id||t.creator_id===me?.id)||requestTab==='overdue'&&!done(t)&&t.due_date<today));
 const firstName=(me?.name||'Коллега').split(' ')[0];
 return <SidebarProvider style={{'--sidebar-width':'244px'} as CSSProperties}>
  <Sidebar className="portal-sidebar"><SidebarHeader className="brand-area"><a className="brand" href="/" onClick={e=>{e.preventDefault();navigate('overview')}}><span className="brand-icon"><Zap size={25} fill="currentColor"/></span><span>ВОЛЬТ<small>ПОРТАЛ ЭЛЕКТРОСЛУЖБЫ</small></span></a></SidebarHeader>
   <SidebarContent><div className="organization"><span className="org-icon"><Cpu size={19}/></span><div><strong>Рабочее пространство</strong><small>Электрослужба компании</small></div></div><p className="nav-label">РАБОТА</p><SidebarMenu className="portal-menu">{navigation.map(item=><NavItem key={item.key} item={item} current={section} navigate={navigate} count={item.key==='requests'?active.filter(t=>t.kind==='request').length:undefined}/>)}</SidebarMenu>
   {(manage||admin)&&<><p className="nav-label nav-label-second">УПРАВЛЕНИЕ</p><SidebarMenu className="portal-menu">{admin&&<NavItem item={{key:'team',label:'Команда и права',icon:Users}} current={section} navigate={navigate} count={pending.length}/>}<NavItem item={{key:'activity',label:'Журнал событий',icon:History}} current={section} navigate={navigate}/></SidebarMenu></>}
   <div className="sidebar-note"><span className="sidebar-note-icon"><Sparkles size={19}/></span><strong>Планируйте на шаг вперёд</strong><p>Прогноз сроков и загрузки на основе истории работ.</p><button onClick={()=>navigate('analytics')}>Открыть аналитику <ArrowUpRight size={15}/></button></div></SidebarContent>
   <SidebarFooter className="sidebar-bottom"><SidebarMenu><NavItem item={{key:'help',label:'Помощь и регламент',icon:CircleHelp}} current={section} navigate={navigate}/></SidebarMenu><button className="profile-mini" onClick={()=>live.me?navigate('profile'):setModal('register')}><Avatar person={me??undefined}/><span><strong>{me?.name??'Личный кабинет'}</strong><small>{me?roleLabels[me.role]:'Войти в портал'}</small></span><Settings2 size={17}/></button></SidebarFooter>
  </Sidebar>
  <div className="app-area"><header className="topbar"><div className="breadcrumb"><SidebarTrigger className="mobile-menu"/><span>Рабочее пространство</span><ChevronRight size={14}/><strong>{navigation.find(n=>n.key===section)?.label??pageNames[section]}</strong></div><div className="topbar-tools"><div className="top-search"><Search size={17}/><input aria-label="Поиск по заявкам" placeholder="Поиск по заявкам…" value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')navigate('requests')}}/><kbd>↵</kbd></div><button className="icon-button" aria-label="Обновить данные" onClick={async()=>{try{await refresh();toast.success("Данные обновлены")}catch(e){toast.error(e instanceof Error?e.message:"Не удалось обновить")}}}><RefreshCw size={18}/></button><button className="icon-button notifications-button" aria-label="Уведомления" onClick={()=>setNotifications(true)}><Bell size={20}/>{overdue.length+pending.length>0&&<i/>}</button><span className="topbar-separator"/><button className="top-avatar" aria-label="Личный кабинет" onClick={()=>live.me?navigate('profile'):setModal('register')}><Avatar person={me??undefined} small/></button></div></header>
  <main className="workspace">
   {initial.error&&<div className="error-banner"><TriangleAlert size={18}/>{initial.error}<button onClick={()=>window.location.reload()}>Повторить</button></div>}
   <div className="page-heading"><div><div className="eyebrow">{section==='overview'?dateLabel(today,{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'ЭЛЕКТРОСЛУЖБА / '+(navigation.find(n=>n.key===section)?.label??pageNames[section])}</div><h1>{pageNames[section]??pageNames.overview}</h1><p>{section==='overview'?'Все работы под контролем. От первой заявки до планового ремонта.':section==='requests'?'Принимайте, назначайте и отслеживайте работы в одном месте.':section==='ppr'?'Плановые ремонты, ответственные и прогноз выполнения.':section==='analytics'?'Оценивайте сроки и загрузку до того, как возникнет задержка.':section==='equipment'?'Единый реестр оборудования и история его обслуживания.':section==='team'?'Назначайте роли и управляйте доступом сотрудников.':section==='profile'?`Ваш профиль и доступные возможности, ${firstName}.`:''}</p></div><div className="page-actions">{section==='overview'&&<Choice label="Период отчёта" value={period} onChange={setPeriod} options={[{value:'7',label:'Последние 7 дней'},{value:'30',label:'Последние 30 дней'}]}/>} {!restricted&&<Button className="primary-button" onClick={()=>{setEquipmentEdit(undefined);setModal(section==='ppr'&&manage?'plan':section==='equipment'&&manage?'equipment':'request')}}><Plus size={18}/>{section==='ppr'&&manage?'Создать график':section==='equipment'&&manage?'Добавить оборудование':'Новая заявка'}</Button>}</div></div>
   {restricted?<div className="panel pending-panel"><span className="pending-icon"><ShieldCheck size={34}/></span><h2>{me?.role==='blocked'?'Доступ приостановлен':'Профиль отправлен на одобрение'}</h2><p>{me?.role==='blocked'?'Обратитесь к администратору компании.':'Администратор назначит вам роль и права. После этого здесь появятся ваши заявки и задачи.'}</p><Button variant="outline" onClick={async()=>{try{await refresh();toast.success('Статус обновлён')}catch(e){toast.error(String(e))}}}><RefreshCw size={16}/>Проверить статус</Button><p className="muted">{me?.name} · {me?.department}</p></div>:<>
   {section==='overview'&&<>
    <div className="kpi-grid">
     <Kpi label="Активные заявки" value={active.filter(t=>t.kind==='request').length} icon={ClipboardList} tone="green" footer={<><span className="kpi-meta-green">{active.filter(t=>t.status==='new'&&t.kind==='request').length} новых</span><span>ожидают назначения</span></>} onClick={()=>{setRequestTab('active');navigate('requests')}}/>
     <Kpi label="В работе" value={active.filter(t=>t.status==='in_progress').length} icon={Wrench} tone="blue" footer={<><span className="avatar-stack">{data.people.filter(p=>p.role==='electrician').slice(0,3).map(p=><Avatar key={p.id} person={p} small/>)}</span><span>электромонтёров: {data.people.filter(p=>p.role==='electrician').length}</span></>} onClick={()=>{setRequestTab('active');navigate('requests')}}/>
     <Kpi label="Выполнено за период" value={completed.length} icon={CircleCheck} tone="mint" footer={<><CheckCheck size={15} className="text-green"/><span>принято заказчиками</span></>} onClick={()=>{setRequestTab('all');navigate('requests')}}/>
     <Kpi label="Просрочено" value={overdue.length} icon={Clock3} tone="orange" footer={<><span className="kpi-meta-orange">Требуют внимания</span><ArrowUpRight size={15}/></>} onClick={()=>{setRequestTab('overdue');navigate('requests')}}/>
    </div>
    <div className="overview-grid"><Panel title="Заявки в работе" subtitle="Приоритетные и последние обращения" action={<button className="text-action" onClick={()=>navigate('requests')}>Все заявки <ArrowRight size={15}/></button>} className="requests-panel"><TicketTable tickets={active.filter(t=>t.kind==='request').slice(0,5)} people={data.people} onSelect={setSelected} compact/><div className="panel-bottom"><span><CircleDot size={14}/>Обновлено при загрузке</span><button onClick={()=>{setRequestTab('overdue');navigate('requests')}}>Показать просроченные <ChevronRight size={14}/></button></div></Panel>
     <ForecastCard predictions={predictions} onClick={()=>navigate('analytics')}/>
    </div>
    <div className="bottom-grid"><Panel title="Ближайшие работы ППР" subtitle="Плановое обслуживание на неделю" action={<button className="text-action" onClick={()=>navigate('ppr')}>Календарь <ArrowRight size={15}/></button>}><PprList tickets={ppr.filter(t=>!done(t)).sort((a,b)=>a.scheduled_date.localeCompare(b.scheduled_date)).slice(0,3)} people={data.people} predictions={predictions} onSelect={setSelected}/></Panel><Panel title="Загрузка команды" subtitle="Ближайшие 7 дней · плановые часы" action={<span className="small-pill">{data.people.filter(p=>p.role==='electrician').length} чел.</span>}><Workload people={data.people} tickets={active}/></Panel></div>
    <div className="workspace-foot"><span><ShieldCheck size={14}/>Доступ к данным определяется вашей ролью</span><span>ВОЛЬТ · Электрослужба</span></div>
   </>}
   {section==='requests'&&<Panel title="Журнал заявок" action={<Button variant="outline" onClick={()=>exportCSV(filtered)}><Download size={16}/>Экспорт</Button>}><div className="filter-row"><Tabs value={requestTab} onValueChange={setRequestTab}><TabsList variant="line"><TabsTrigger value="active">Активные <b>{active.length}</b></TabsTrigger><TabsTrigger value="all">Все</TabsTrigger><TabsTrigger value="mine">Мои</TabsTrigger><TabsTrigger value="overdue">Просрочено <b>{overdue.length}</b></TabsTrigger></TabsList></Tabs><div className="filter-actions"><div className="inline-search"><Search size={16}/><Input aria-label="Найти заявку" placeholder="Номер, название, объект" value={search} onChange={e=>setSearch(e.target.value)}/></div><Choice label="Приоритет" value={priorityFilter} onChange={setPriorityFilter} options={[{value:'all',label:'Все приоритеты'},...Object.entries(priorityLabels).map(([value,label])=>({value,label}))]}/></div></div><TicketTable tickets={filtered} people={data.people} onSelect={setSelected}/><div className="panel-bottom"><span>Найдено: {filtered.length}</span><span>Нажмите на заявку, чтобы открыть детали</span></div></Panel>}
   {section==='ppr'&&<><div className="ppr-summary"><span><CalendarClock size={19}/><strong>{ppr.filter(t=>!done(t)).length}</strong> запланировано</span><span><CircleCheck size={19}/><strong>{ppr.filter(t=>t.status==='closed').length}</strong> выполнено</span><span className="text-orange"><TriangleAlert size={19}/><strong>{predictions.ppr.filter(t=>t.late).length}</strong> с риском задержки</span><button className="text-action" onClick={()=>navigate('analytics')}>Посмотреть прогноз <Sparkles size={16}/></button></div><Panel title="Календарь обслуживания" action={<div className="calendar-controls"><Button variant="outline" size="icon" aria-label="Предыдущая неделя" onClick={()=>setWeekOffset(v=>v-7)}><ChevronLeft size={17}/></Button><Button variant="outline" onClick={()=>setWeekOffset(0)}>Сегодня</Button><Button variant="outline" size="icon" aria-label="Следующая неделя" onClick={()=>setWeekOffset(v=>v+7)}><ChevronRight size={17}/></Button></div>}><div className="calendar-range">{dateLabel(dayISO(weekOffset))} — {dateLabel(dayISO(weekOffset+6),{day:'numeric',month:'long',year:'numeric'})}</div><div className="week-grid">{Array.from({length:7},(_,i)=>{const date=dayISO(weekOffset+i),tasks=ppr.filter(t=>t.scheduled_date===date);return <div className={`week-day ${date===today?'is-today':''}`} key={date}><div className="day-heading"><span>{dateLabel(date,{weekday:'short'})}</span><b>{dateLabel(date,{day:'numeric'})}</b>{date===today&&<em>Сегодня</em>}</div><div className="day-tasks">{tasks.map(t=><button className={`calendar-job ${done(t)?'job-complete':''}`} onClick={()=>setSelected(t.id)} key={t.id}><span>{formatHours(t.estimated_hours)} ч · {t.location}</span><strong>{t.title}</strong><div><Avatar person={data.people.find(p=>p.id===t.assignee_id)} small/><span>{statusLabels[t.status]}</span></div></button>)}{!tasks.length&&<span className="day-empty">Нет работ</span>}</div></div>})}</div></Panel><Panel className="section-spaced" title="Все работы ППР" action={<Button variant="outline" onClick={()=>exportCSV(ppr)}><Download size={16}/>Выгрузить график</Button>}><TicketTable tickets={ppr} people={data.people} onSelect={setSelected}/></Panel><p className="note-text">Повторения создаются на выбранное число циклов. Каждую работу можно переназначить или отменить в её карточке.</p></>}
   {section==='equipment'&&<><div className="equipment-grid">{data.equipment.map(eq=><article className="panel equipment-card" key={eq.id}><div className="equipment-top"><span className="equipment-symbol"><Cpu size={26}/></span><span className={`equipment-condition condition-${eq.condition}`}>{eq.condition==='normal'?'Исправно':eq.condition==='attention'?'Требует внимания':'В ремонте'}</span></div><div className="equipment-code">{eq.code} · {eq.category}</div><h2>{eq.name}</h2><p><MapPin size={15}/>{eq.location}</p><div className="equipment-facts"><span>Активных работ <b>{active.filter(t=>t.equipment_id===eq.id).length}</b></span><span>Выполнено <b>{data.tickets.filter(t=>t.equipment_id===eq.id&&t.status==='closed').length}</b></span></div><p className="equipment-notes">{eq.notes||'Дополнительных сведений нет'}</p><div className="equipment-actions"><Button variant="outline" onClick={()=>{setSearch(eq.location);setRequestTab('all');navigate('requests')}}>Работы на объекте <ArrowUpRight size={15}/></Button>{manage&&<Button variant="ghost" size="icon" aria-label={`Редактировать ${eq.name}`} onClick={()=>{setEquipmentEdit(eq);setModal('equipment')}}><Settings2 size={17}/></Button>}</div></article>)}</div>{!data.equipment.length&&<div className="panel"><NoData icon={Cpu} title="Добавьте оборудование" text="Укажите инвентарный номер и расположение, чтобы связать оборудование с заявками и ППР."/></div>}</>}
   {section==='digital-twin'&&<DigitalTwin data={data} tickets={data.tickets}/>}
   {section==='analytics'&&<><div className="analytics-banner"><span className="ai-icon"><Sparkles size={24}/></span><div><h2>{predictions.method==='knn'?'Прогноз на основе истории работ':'Начинаем собирать историю работ'}</h2><p>{predictions.method==='knn'?`Модель обучается на ${predictions.samples} выполненных работах с указанными трудозатратами.`:`Для обучения нужны хотя бы 5 принятых работ с фактическими часами. Сейчас: ${predictions.samples}. Пока используются плановые часы.`}</p></div><span className="model-tag">{predictions.method==='knn'?'Модель kNN':'Расчётный режим'}</span></div><div className="analytics-grid"><Panel title="План и прогноз трудозатрат" subtitle="Для ближайших незавершённых работ ППР" action={<span className="chart-legend"><i/>План <i/>Прогноз</span>}><div className="bar-chart">{predictions.ppr.slice(0,6).map((p,i)=>{const t=data.tickets.find(t=>t.id===p.id)!;const max=Math.max(...predictions.ppr.slice(0,6).flatMap(r=>[r.hours,data.tickets.find(t=>t.id===r.id)!.estimated_hours]),1);return <div className="bar-pair" key={p.id}><div className="bar-pair-bars"><div className="plan-bar" style={{height:`${t.estimated_hours/max*150}px`}}><span>{formatHours(t.estimated_hours)}</span></div><div className="forecast-bar" style={{height:`${p.hours/max*150}px`}}><span>{formatHours(p.hours)}</span></div></div><button onClick={()=>setSelected(p.id)} title={t.title}>#{t.number}</button></div>})}{!predictions.ppr.length&&<NoData title="Нет работ для прогноза" text="Создайте график ППР, чтобы сравнить план и ожидаемые трудозатраты."/>}</div></Panel><Panel title="Параметры прогноза" subtitle="Проверьте, как загрузка влияет на сроки"><Field label="Рабочих часов в день на человека"><Choice label="Часов в день" value={capacity} onChange={setCapacity} options={[{value:'4',label:'4 часа'},{value:'6',label:'6 часов'},{value:'8',label:'8 часов'}]}/></Field><div className="forecast-facts"><div><span>Ожидаемые трудозатраты</span><strong>{predictions.hours} ч</strong></div><div><span>Работ с задержкой</span><strong className="text-orange">{predictions.late}</strong></div><div><span>Без исполнителя</span><strong>{predictions.unassigned}</strong></div></div><p className="note-text">Сценарий: пятидневная неделя, без праздников и отсутствий. Параметр часов меняет этот расчёт и не изменяет график.</p></Panel></div><Panel className="section-spaced" title="Прогноз выполнения" subtitle="Приоритет, очередь работ и назначенный исполнитель"><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Работа</TableHead><TableHead>Плановый срок</TableHead><TableHead>Прогноз</TableHead><TableHead>Трудозатраты</TableHead><TableHead>Оценка</TableHead></TableRow></TableHeader><TableBody>{predictions.jobs.map(p=>{const t=data.tickets.find(t=>t.id===p.id)!;return <TableRow key={p.id}><TableCell><button className="table-title" onClick={()=>setSelected(p.id)}>{t.title}</button><small>#{t.number} · {t.location}</small></TableCell><TableCell>{dateLabel(t.due_date)}</TableCell><TableCell>{p.date?dateLabel(p.date):'Нужен исполнитель'}</TableCell><TableCell>{formatHours(p.hours)} ч<small>Ориентир: {formatHours(p.low)}–{formatHours(p.high)} ч</small></TableCell><TableCell><span className={`forecast-status ${p.late?'risk':p.unassigned?'unassigned':'on-time'}`}>{p.unassigned?'Не рассчитан':p.late?'Риск задержки':'В пределах срока'}</span></TableCell></TableRow>})}</TableBody></Table></div>{!predictions.jobs.length&&<NoData title="Все работы завершены" text="Прогноз появится после создания новых заявок."/>}</Panel><div className="method-note"><Info size={20}/><div><h3>Как устроен прогноз</h3><p>Модель k ближайших соседей сравнивает тип работы, оборудование, приоритет и плановую длительность с завершёнными работами. Затем работы последовательно распределяются по исполнителям. Диапазон часов показывает разброс наблюдений, а не статистически подтверждённый доверительный интервал. Работы «В работе» учитываются целиком; ожидание материалов, праздники и отпуска могут сдвинуть сроки. Решение об изменении графика принимает диспетчер.</p></div></div></>}
   {section==='team'&&(admin?<><div className="role-overview">{(['employee','electrician','dispatcher','admin'] as Role[]).map(r=><div className="panel role-card" key={r}><ShieldCheck size={20}/><h3>{roleLabels[r]}</h3><p>{r==='employee'?'Создаёт свои заявки и принимает выполненные работы.':r==='electrician'?'Ведёт назначенные работы, заполняет отчёт и фактические часы.':r==='dispatcher'?'Назначает исполнителей, управляет ППР и оборудованием.':'Все возможности и назначение ролей сотрудникам.'}</p></div>)}</div><Panel title="Сотрудники" subtitle="Новая регистрация не даёт доступ к данным компании"><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Сотрудник</TableHead><TableHead>Подразделение</TableHead><TableHead>Роль и права</TableHead><TableHead>Статус</TableHead></TableRow></TableHeader><TableBody>{data.people.map(p=><TableRow key={p.id}><TableCell><div className="person-cell"><Avatar person={p}/><div><strong>{p.name}{p.id===me?.id?' (вы)':''}</strong><small>{p.email||p.position}</small></div></div></TableCell><TableCell>{p.department}</TableCell><TableCell>{p.id===me?.id?<span>{roleLabels[p.role]}</span>:<Choice label={`Роль ${p.name}`} value={p.role} onChange={async value=>{await run('role',{id:p.id,role:value})}} options={Object.entries(roleLabels).map(([value,label])=>({value,label}))}/>}</TableCell><TableCell><span className={`access-state ${p.role==='pending'?'pending':p.role==='blocked'?'blocked':''}`}>{p.role==='pending'?'Ожидает одобрения':p.role==='blocked'?'Заблокирован':'Активен'}</span></TableCell></TableRow>)}</TableBody></Table></div></Panel><div className="method-note"><LockKeyhole size={20}/><div><h3>Подключение сотрудников</h3><p>Администратор открывает сотрудникам доступ к сайту в настройках доступа Sites. Сотрудник входит через ChatGPT и заполняет профиль. После этого назначьте ему роль здесь. Только одобрение роли открывает рабочие данные. Не предоставляйте доступ к сайту посторонним.</p></div></div></>:<NoData title="Раздел доступен администратору" text="Роли и права назначает администратор компании."/>)}
   {section==='activity'&&(manage?<Panel title="История изменений" subtitle="Последние 300 доступных событий"><div className="activity-list">{data.activity.map(a=><div className="activity-row" key={a.id}><span className="activity-icon"><History size={17}/></span><div><strong>{a.actor_name}</strong><p>{a.message}</p></div><time>{dateLabel(a.created_at)} · {new Date(a.created_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time>{a.ticket_id&&<Button variant="ghost" size="icon" aria-label="Открыть заявку" onClick={()=>setSelected(a.ticket_id)}><ArrowUpRight size={16}/></Button>}</div>)}</div>{!data.activity.length&&<NoData title="Событий пока нет" text="Здесь будет история создания и изменения работ."/>}</Panel>:<NoData title="Раздел доступен диспетчеру"/>)}
   {section==='profile'&&<div className="profile-grid"><Panel title="Мой профиль"><div className="profile-hero"><Avatar person={me??undefined}/><div><h2>{me?.name}</h2><span className="small-pill">{me?roleLabels[me.role]:''}</span></div></div><ProfileForm person={me??undefined} viewer={live.viewer} busy={busy} onSave={async p=>run('profile',p)}/>{me&&<a className="logout-link" href="/signout-with-chatgpt?return_to=%2F" target="_top"><LogOut size={16}/>Выйти из аккаунта</a>}</Panel><Panel title="Мои задачи"><div className="profile-count"><strong>{active.filter(t=>t.assignee_id===me?.id).length}</strong><span>назначено мне</span></div><div className="profile-count"><strong>{active.filter(t=>t.creator_id===me?.id).length}</strong><span>моих открытых заявок</span></div><p className="note-text">Роль и права изменяет администратор. Вход защищён учётной записью ChatGPT.</p><Button variant="outline" onClick={()=>{setRequestTab('mine');navigate('requests')}}>Перейти к моим заявкам<ArrowRight size={16}/></Button></Panel></div>}
   {section==='help'&&<div className="help-grid"><Panel title="От обращения до результата"><ol className="steps-list"><li><b>01</b><div><h3>Создайте заявку</h3><p>Опишите неисправность, укажите место и приоритет. Фото можно добавить в карточке заявки.</p></div></li><li><b>02</b><div><h3>Назначьте исполнителя</h3><p>Диспетчер определяет электромонтёра, срок и плановые трудозатраты.</p></div></li><li><b>03</b><div><h3>Зафиксируйте выполнение</h3><p>Электромонтёр переводит заявку в работу, затем указывает результат и фактические часы и отправляет на проверку.</p></div></li><li><b>04</b><div><h3>Примите работу</h3><p>Автор заявки или диспетчер принимает результат. Завершённая работа участвует в обучении прогноза.</p></div></li></ol></Panel><Panel title="Плановое обслуживание"><p className="help-text">В разделе «График ППР» диспетчер создаёт серию работ, задаёт первую дату, интервал в днях и количество повторений. Каждое повторение становится отдельной работой с исполнителем и сроком.</p><p className="help-text">Прогноз доступен в разделе «ИИ-аналитика». Он пересчитывается по текущей очереди и фактическим часам из принятых работ.</p><div className="safety-note"><TriangleAlert size={20}/><p>При аварийной ситуации используйте принятый в компании порядок экстренного оповещения. Портал не заменяет оперативную связь и наряд-допуск.</p></div><Button variant="outline" onClick={()=>navigate('ppr')}>Открыть график ППР <ArrowRight size={16}/></Button></Panel></div>}
   </>}
  </main></div>
  <Dialog open={modal!==null} onOpenChange={o=>{if(!o)setModal(null)}}><DialogContent className="portal-dialog"><DialogHeader><DialogTitle>{modal==='request'?'Новая заявка':modal==='plan'?'Новый график ППР':modal==='equipment'?(equipmentEdit?'Карточка оборудования':'Добавить оборудование'):'Регистрация в электрослужбе'}</DialogTitle><DialogDescription>{modal==='request'?'Опишите проблему — диспетчер назначит исполнителя.':modal==='plan'?'Создайте серию работ с заданной периодичностью.':modal==='equipment'?'Данные будут доступны в реестре оборудования.':live.firstRegistration?'Вы первый пользователь закрытого портала. После регистрации вам будет назначена роль администратора.':'Заполните профиль. Роль и доступ назначит администратор компании.'}</DialogDescription></DialogHeader>
   {modal==='register'?(live.viewer?<ProfileForm viewer={live.viewer} busy={busy} register onSave={async p=>{const r=await run('register',p);if(r.ok){setModal(null);navigate('overview')}return r}}/>:<div className="sign-in-box"><span className="sign-in-icon"><ShieldCheck size={32}/></span><p>Для личного кабинета используется защищённый вход через ChatGPT.</p><Button asChild className="primary-button"><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Войти через ChatGPT <ArrowRight size={17}/></a></Button></div>):modal==='equipment'?<EquipmentForm equipment={equipmentEdit} busy={busy} onSave={async p=>{const r=await run('equipment',p);if(r.ok)setModal(null);return r}}/>:<JobForm key={modal??''} type={modal==='plan'?'plan':'request'} equipment={data.equipment} people={data.people} busy={busy} onSave={async p=>{const r=await run(modal==='plan'?'create_plan':'create_ticket',p);if(r.ok){setModal(null);if(modal==='plan')navigate('ppr');else if(r.id)setSelected(r.id)}return r}}/>}
  </DialogContent></Dialog>
  <Sheet open={!!selectedTicket} onOpenChange={o=>{if(!o)setSelected(null)}}><SheetContent className="ticket-sheet" side="right"><SheetHeader><SheetTitle>Заявка №{selectedTicket?.number}</SheetTitle><SheetDescription>{selectedTicket?.kind==='ppr'?'Планово-предупредительный ремонт':'Обращение сотрудника'}</SheetDescription></SheetHeader>{selectedTicket&&<TicketDetails key={`${selectedTicket.id}-${selectedTicket.updated_at}`} ticket={selectedTicket} data={data} busy={busy} run={run} refresh={refresh}/>}</SheetContent></Sheet>
  <Sheet open={notifications} onOpenChange={setNotifications}><SheetContent className="notifications-sheet"><SheetHeader><SheetTitle>Требует внимания</SheetTitle><SheetDescription>Сроки работ и новые регистрации</SheetDescription></SheetHeader><div className="notifications-list">{pending.length>0&&admin&&<button onClick={()=>{navigate('team');setNotifications(false)}}><Users size={20}/><span><strong>Ожидают доступа: {pending.length}</strong><small>Назначьте роли новым сотрудникам</small></span><ChevronRight size={18}/></button>}{overdue.map(t=><button key={t.id} onClick={()=>{setNotifications(false);setSelected(t.id)}}><Clock3 size={20}/><span><strong>{t.title}</strong><small>Просрочено · №{t.number} · до {dateLabel(t.due_date)}</small></span><ChevronRight size={18}/></button>)}{!overdue.length&&!pending.length&&<NoData title="Всё под контролем" text="Нет просроченных работ или ожидающих регистраций." icon={CircleCheck}/>}</div></SheetContent></Sheet>
  <Toaster position="bottom-right" richColors closeButton/>
 </SidebarProvider>
}

function Kpi({label,value,icon:Icon,tone,footer,onClick}:{label:string;value:number;icon:typeof Zap;tone:string;footer:ReactNode;onClick:()=>void}){return <button className="kpi-card" onClick={onClick}><div className="kpi-top"><span>{label}</span><span className={`kpi-icon tone-${tone}`}><Icon size={20}/></span></div><strong className="kpi-value">{value}<ArrowUpRight size={21}/></strong><div className="kpi-footer">{footer}</div></button>}
function TicketTable({tickets,people,onSelect,compact=false}:{tickets:Ticket[];people:Person[];onSelect:(id:string)=>void;compact?:boolean}){return <><div className={`table-scroll ${compact?'compact-table':''}`}><Table><TableHeader><TableRow><TableHead>Заявка</TableHead><TableHead>Приоритет</TableHead><TableHead>Статус</TableHead>{!compact&&<><TableHead>Срок</TableHead><TableHead>Исполнитель</TableHead></>}<TableHead className="table-arrow"><span className="sr-only">Открыть</span></TableHead></TableRow></TableHeader><TableBody>{tickets.map(t=><TableRow key={t.id} className="ticket-row"><TableCell><button className="ticket-link" onClick={()=>onSelect(t.id)}><span className="ticket-reference">#{t.number}<i/>{t.location}{t.kind==='ppr'&&<em>ППР</em>}</span><strong>{t.title}</strong></button></TableCell><TableCell><PriorityMark priority={t.priority}/></TableCell><TableCell><StateBadge status={t.status}/></TableCell>{!compact&&<><TableCell className={!done(t)&&t.due_date<todayISO()?'overdue-date':''}>{dateLabel(t.due_date)}</TableCell><TableCell>{t.assignee_id?<div className="person-cell"><Avatar person={people.find(p=>p.id===t.assignee_id)} small/><span>{people.find(p=>p.id===t.assignee_id)?.name??'Назначен'}</span></div>:<span className="muted">Не назначен</span>}</TableCell></>}<TableCell><button className="row-arrow" aria-label={`Открыть заявку ${t.number}`} onClick={()=>onSelect(t.id)}><ChevronRight size={17}/></button></TableCell></TableRow>)}</TableBody></Table></div>{!tickets.length&&<NoData title="Заявок не найдено" text="Измените фильтры или создайте первую заявку."/>}</>}
function ForecastCard({predictions,onClick}:{predictions:ReturnType<typeof forecast>;onClick:()=>void}){const assigned=predictions.ppr.filter(p=>!p.unassigned),onTime=assigned.filter(p=>!p.late),value=assigned.length?Math.round(onTime.length/assigned.length*100):0;return <section className="forecast-card"><div className="forecast-card-header"><span><Sparkles size={20}/>ИИ-прогноз</span><b>ППР</b></div><h2>Планируйте уверенно.<br/>Предупреждайте задержки.</h2><p>Оценка выполнения текущего плана с учётом загрузки команды</p><div className="forecast-gauge-row"><div className="forecast-ring" style={{'--ring-progress':`${value}%`} as CSSProperties}><div><strong>{assigned.length?value:'—'}<small>{assigned.length?'%':''}</small></strong><span>в срок</span></div></div><div className="gauge-caption"><strong>{onTime.length} из {assigned.length}</strong><span>назначенных работ<br/>укладываются в срок</span><small>{predictions.method==='knn'?'На основе истории':'По плановым часам'}</small></div></div><div className="forecast-alert"><TriangleAlert size={17}/><div><strong>{predictions.late?`${predictions.late} работ с риском задержки`:'Проверьте готовность плана'}</strong><p>{predictions.unassigned?`Без исполнителя: ${predictions.unassigned}. Назначьте ответственных.`:'Учитывайте материалы и доступ к оборудованию.'}</p></div></div><button onClick={onClick}>Открыть аналитику <ArrowUpRight size={17}/></button><span className="forecast-caption">Оценка сроков · не гарантия выполнения</span></section>}
function PprList({tickets,people,predictions,onSelect}:{tickets:Ticket[];people:Person[];predictions:ReturnType<typeof forecast>;onSelect:(id:string)=>void}){return <div className="ppr-list">{tickets.map(t=>{const p=predictions.jobs.find(p=>p.id===t.id);return <button className="ppr-item" onClick={()=>onSelect(t.id)} key={t.id}><span className="ppr-date"><b>{dateLabel(t.scheduled_date,{day:'2-digit'})}</b><small>{dateLabel(t.scheduled_date,{month:'short'}).replace('.','')}</small></span><span className="ppr-info"><strong>{t.title}</strong><small>{t.location}<i/> {formatHours(t.estimated_hours)} ч · {people.find(p=>p.id===t.assignee_id)?.name??'Не назначен'}</small></span><span className={`ppr-indicator ${p?.late?'risk':''}`}>{p?.late?<TriangleAlert size={16}/>:<CalendarClock size={16}/>}</span><ChevronRight size={16}/></button>})}{!tickets.length&&<NoData title="План ещё не создан" text="Добавьте график планового обслуживания." icon={CalendarDays}/>}</div>}
function Workload({people,tickets}:{people:Person[];tickets:Ticket[]}){return <div className="workload-list">{people.filter(p=>p.role==='electrician').map((p,i)=>{const assigned=tickets.filter(t=>t.assignee_id===p.id&&t.scheduled_date<=dayISO(6)),hours=assigned.reduce((s,t)=>s+t.estimated_hours,0);return <div className="workload-row" key={p.id}><Avatar person={p}/><div><div className="workload-name"><strong>{p.name}</strong><span>{formatHours(hours)} ч</span></div><Progress value={Math.min(100,hours/30*100)} className={`workload-progress progress-${i%3}`} aria-label={`${p.name}: ${hours} часов из 30`}/><div className="workload-meta"><span>{assigned.length} работ</span><span>из 30 ч / нед.</span></div></div></div>})}{!people.some(p=>p.role==='electrician')&&<NoData title="Подключите команду" text="Назначьте сотрудникам роль электромонтёра." icon={Users}/>}</div>}

function ProfileForm({person,viewer,busy,register=false,onSave}:{person?:Person;viewer:PortalState['viewer'];busy:boolean;register?:boolean;onSave:(p:unknown)=>Promise<{ok:boolean}>}){return <form className="portal-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await onSave(Object.fromEntries(f))}}><Field label="Имя и фамилия"><Input name="name" required minLength={2} maxLength={100} defaultValue={person?.name??viewer?.name??''} placeholder="Иван Петров" autoComplete="name"/></Field><Field label="Электронная почта" hint="Адрес из учётной записи входа"><Input value={person?.email??viewer?.email??''} readOnly aria-label="Электронная почта"/></Field><div className="form-grid"><Field label="Подразделение"><Input name="department" required minLength={2} maxLength={100} defaultValue={person?.department??''} placeholder="Производственный цех"/></Field><Field label="Должность"><Input name="position" maxLength={100} defaultValue={person?.position??''} placeholder="Начальник смены"/></Field></div><Field label="Телефон или внутренний номер"><Input name="phone" type="tel" maxLength={40} defaultValue={person?.phone??''} placeholder="Внутренний номер"/></Field>{register&&<p className="form-note"><ShieldCheck size={17}/>Роль назначает администратор после регистрации.</p>}<Button disabled={busy} type="submit" className="primary-button form-submit">{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} {register?'Зарегистрироваться':'Сохранить профиль'}</Button></form>}
function JobForm({type,equipment,people,busy,onSave}:{type:'request'|'plan';equipment:Equipment[];people:Person[];busy:boolean;onSave:(p:unknown)=>Promise<{ok:boolean}>}){
 const [priority,setPriority]=useState('normal'),[eq,setEq]=useState('none'),[assignee,setAssignee]=useState('none'),[interval,setInterval]=useState('30');const plan=type==='plan';
 return <form className="portal-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),p=Object.fromEntries(f);await onSave({...p,equipment_id:eq==='none'?null:eq,estimated_hours:Number(p.estimated_hours),...(plan?{assignee_id:assignee==='none'?null:assignee,interval_days:Number(interval),occurrences:Number(p.occurrences)}:{priority})})}}><Field label={plan?'Название работ':'Что случилось?'}><Input autoFocus name="title" required minLength={5} maxLength={180} placeholder={plan?'Плановый осмотр распределительного щита':'Например, не работает освещение в цехе'}/></Field><Field label={plan?'Состав работ':'Описание неисправности'}><Textarea name="description" required={!plan} minLength={plan?0:10} maxLength={5000} rows={3} placeholder={plan?'Перечень работ по регламенту предприятия':'Где находится проблема, когда появилась и как проявляется'}/></Field><Field label="Оборудование"><Choice label="Оборудование" value={eq} onChange={setEq} options={[{value:'none',label:'Не выбрано'},...equipment.map(e=>({value:e.id,label:`${e.code} · ${e.name}`}))]}/></Field><Field label="Объект / расположение"><Input key={eq} name="location" required minLength={2} maxLength={150} defaultValue={equipment.find(e=>e.id===eq)?.location??''} placeholder="Цех, этаж, помещение"/></Field><div className="form-grid">{plan?<Field label="Первая дата"><Input name="start_date" type="date" defaultValue={todayISO()} required/></Field>:<Field label="Приоритет"><Choice label="Приоритет" value={priority} onChange={setPriority} options={Object.entries(priorityLabels).map(([value,label])=>({value,label}))}/></Field>}<Field label={plan?'Плановые трудозатраты, ч':'Желаемый срок'}>{plan?<Input name="estimated_hours" type="number" min="0.25" max="1000" step="0.25" defaultValue="2" required/>:<Input name="due_date" type="date" defaultValue={dayISO(1)} required/>}</Field></div>{!plan&&<input name="estimated_hours" type="hidden" value="2"/>}{plan&&<><div className="form-grid"><Field label="Периодичность"><Choice label="Периодичность" value={interval} onChange={setInterval} options={[{value:'7',label:'Каждые 7 дней'},{value:'30',label:'Каждые 30 дней'},{value:'90',label:'Каждые 90 дней'},{value:'180',label:'Каждые 180 дней'},{value:'365',label:'Каждые 365 дней'}]}/></Field><Field label="Количество повторений"><Input name="occurrences" type="number" min="1" max="12" defaultValue="3" required/></Field></div><Field label="Ответственный электромонтёр"><Choice label="Электромонтёр" value={assignee} onChange={setAssignee} options={[{value:'none',label:'Назначить позже'},...people.filter(p=>p.role==='electrician').map(p=>({value:p.id,label:p.name}))]}/></Field><p className="form-note"><Info size={16}/>Каждое повторение появится в календаре как отдельная работа.</p></>}{!plan&&priority==='critical'&&<p className="form-note warning"><TriangleAlert size={17}/>Сообщите об аварии по оперативной связи предприятия.</p>}<Button type="submit" disabled={busy} className="primary-button form-submit">{busy?<Loader2 size={17} className="spin"/>:<Plus size={17}/>} {plan?'Создать график':'Отправить заявку'}</Button></form>
}
function EquipmentForm({equipment,busy,onSave}:{equipment?:Equipment;busy:boolean;onSave:(p:unknown)=>Promise<{ok:boolean}>}){const [condition,setCondition]=useState(equipment?.condition??'normal');return <form className="portal-form" onSubmit={async e=>{e.preventDefault();await onSave({...Object.fromEntries(new FormData(e.currentTarget)),condition,...(equipment?{id:equipment.id}:{})})}}><Field label="Название"><Input name="name" required minLength={2} maxLength={180} defaultValue={equipment?.name} placeholder="Распределительный щит ЩР-12"/></Field><div className="form-grid"><Field label="Инвентарный номер"><Input name="code" required minLength={2} maxLength={60} defaultValue={equipment?.code} placeholder="ЭО-0012"/></Field><Field label="Категория"><Input name="category" required minLength={2} maxLength={100} defaultValue={equipment?.category} placeholder="Распределительные щиты"/></Field></div><Field label="Расположение"><Input name="location" required minLength={2} maxLength={150} defaultValue={equipment?.location} placeholder="Цех № 1"/></Field><Field label="Состояние"><Choice value={condition} onChange={setCondition} label="Состояние" options={[{value:'normal',label:'Исправно'},{value:'attention',label:'Требует внимания'},{value:'repair',label:'В ремонте'}]}/></Field><Field label="Сведения и примечания"><Textarea name="notes" rows={3} maxLength={3000} defaultValue={equipment?.notes}/></Field><Button disabled={busy} className="primary-button form-submit" type="submit">{busy?<Loader2 size={17} className="spin"/>:<Check size={17}/>}Сохранить оборудование</Button></form>}
function TicketDetails({ticket:t,data,busy,run,refresh}:{ticket:Ticket;data:PortalState;busy:boolean;run:Mutate;refresh:()=>Promise<PortalState>}){
 const [status,setStatus]=useState(t.status),[assignee,setAssignee]=useState(t.assignee_id??'none'),[comment,setComment]=useState(''),[uploading,setUploading]=useState(false);const role=data.me?.role,manage=manager(role),isTech=role==='electrician'&&t.assignee_id===data.me?.id,isOwner=t.creator_id===data.me?.id;
 const transitions:Record<string,Status[]>={assigned:['in_progress'],in_progress:['waiting','review'],waiting:['in_progress'],review:['in_progress']};
 let statuses:Status[]=manage?['new','assigned','in_progress','waiting','review','closed','cancelled']:[t.status,...(isTech?transitions[t.status]??[]:[]),...(isOwner&&t.status==='review'?['closed' as Status]:[]),...(isOwner&&t.status==='new'?['cancelled' as Status]:[])];statuses=[...new Set(statuses)];
 const canEdit=!done(t)&&(manage||isTech||isOwner&&['new','review'].includes(t.status));
 const events=data.activity.filter(a=>a.ticket_id===t.id),files=data.attachments.filter(a=>a.ticket_id===t.id);
 return <div className="ticket-details"><div className="ticket-detail-badges"><StateBadge status={t.status}/><PriorityMark priority={t.priority}/></div><h2>{t.title}</h2><p className="location-line"><MapPin size={16}/>{t.location}</p><p className="ticket-description">{t.description}</p><div className="ticket-facts"><div><span>Создана</span><strong>{dateLabel(t.created_at)}</strong></div><div><span>Срок</span><strong>{dateLabel(t.due_date)}</strong></div><div><span>Тип</span><strong>{t.kind==='ppr'?'Работа ППР':'Обращение'}</strong></div><div><span>Оборудование</span><strong>{data.equipment.find(e=>e.id===t.equipment_id)?.code??'Не указано'}</strong></div></div>
 {canEdit?<form className="portal-form detail-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await run('update_ticket',{id:t.id,updated_at:t.updated_at,status,assignee_id:assignee==='none'?null:assignee,due_date:f.get('due_date')||t.due_date,estimated_hours:Number(f.get('estimated_hours')||t.estimated_hours),actual_hours:f.has('actual_hours')?(f.get('actual_hours')?Number(f.get('actual_hours')):null):t.actual_hours,result:f.has('result')?String(f.get('result')):t.result})}}><h3>Управление работой</h3><Field label="Статус"><Choice label="Статус" value={status} onChange={v=>setStatus(v as Status)} options={statuses.map(value=>({value,label:statusLabels[value]}))}/></Field>{manage&&<><Field label="Исполнитель"><Choice label="Исполнитель" value={assignee} onChange={v=>{setAssignee(v);if(status==='new'&&v!=='none')setStatus('assigned')}} options={[{value:'none',label:'Не назначен'},...data.people.filter(p=>p.role==='electrician').map(p=>({value:p.id,label:p.name}))]}/></Field><div className="form-grid"><Field label="Срок выполнения"><Input name="due_date" type="date" required defaultValue={t.due_date}/></Field><Field label="План, ч"><Input name="estimated_hours" type="number" min="0.25" max="1000" step="0.25" required defaultValue={t.estimated_hours}/></Field></div></>}{(manage||isTech)&&<><Field label="Фактические трудозатраты, ч"><Input name="actual_hours" type="number" min="0.25" max="1000" step="0.25" defaultValue={t.actual_hours??''} placeholder="Укажите после выполнения" required={['review','closed'].includes(status)}/></Field><Field label="Результат работ"><Textarea name="result" defaultValue={t.result} maxLength={5000} minLength={['review','closed'].includes(status)?5:0} required={['review','closed'].includes(status)} rows={3} placeholder="Что сделано и в каком состоянии оборудование"/></Field></>}{!manage&&!isTech&&t.result&&<div className="completion-report"><h3>Отчёт исполнителя</h3><p>{t.result}</p><span>Факт: {t.actual_hours} ч</span></div>}<Button type="submit" disabled={busy} className="primary-button">{busy?<Loader2 className="spin" size={16}/>:<Check size={16}/>}Сохранить изменения</Button></form>:t.result?<div className="completion-report"><h3>Отчёт исполнителя</h3><p>{t.result}</p><span>Факт: {t.actual_hours} ч</span></div>:null}
 <section className="detail-section"><h3><Paperclip size={17}/>Вложения <span>{files.length}</span></h3>{files.map(f=><a className="attachment-link" key={f.id} href={`/api/attachments?id=${encodeURIComponent(f.id)}`} target="_blank" rel="noreferrer"><FileText size={17}/><span>{f.filename}<small>{Math.round(f.size/1024)} КБ</small></span><Download size={16}/></a>)}<label className={`upload-button ${uploading?'disabled':''}`}><Plus size={16}/>{uploading?'Загрузка…':'Прикрепить файл'}<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" disabled={uploading} onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast.error('Максимальный размер файла — 5 МБ');return;}setUploading(true);const form=new FormData();form.set('file',file);form.set('ticket_id',t.id);try{const r=await fetch('/api/attachments',{method:'POST',body:form});const result=await r.json() as {ok:boolean;id?:string;error?:string};if(!r.ok)throw new Error(result.error??'Не удалось загрузить файл');await refresh();toast.success('Файл прикреплён')}catch(err){toast.error(err instanceof Error?err.message:'Не удалось загрузить файл')}finally{setUploading(false);e.target.value=''}}}/></label><small className="muted">JPG, PNG, WebP или PDF · до 5 МБ</small></section>
 <section className="detail-section"><h3>Комментарии и история</h3><form className="comment-form" onSubmit={async e=>{e.preventDefault();const r=await run('comment',{id:t.id,message:comment});if(r.ok)setComment('')}}><Textarea placeholder="Добавить комментарий…" aria-label="Комментарий" value={comment} maxLength={3000} minLength={1} required onChange={e=>setComment(e.target.value)}/><Button type="submit" size="icon" aria-label="Отправить комментарий" disabled={busy||!comment.trim()}><Send size={17}/></Button></form><div className="comment-list">{events.map(a=><div key={a.id}><div><strong>{a.actor_name}</strong><time>{dateLabel(a.created_at)}</time></div><p className={a.type==='comment'?'':'muted'}>{a.message}</p></div>)}</div></section></div>
}
